'use client';

import { useActionState } from 'react';
import { generateApiDocumentation } from '@/ai/flows/generate-api-documentation';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Terminal, Copy, Check } from 'lucide-react';
import React from 'react';

type GenerateApiDocumentationOutput = {
  documentation: string;
};

type State = {
  data: GenerateApiDocumentationOutput | null;
  error: string | null;
};

export default function ApiDocGenerator() {
  const [copied, setCopied] = React.useState(false);

  const [state, formAction, isPending] = useActionState<State, FormData>(
    async (previousState, formData) => {
      const apiDefinition = formData.get('apiDefinition') as string;
      if (!apiDefinition) {
        return {
          data: null,
          error: 'API definition cannot be empty.',
        };
      }

      try {
        const result = await generateApiDocumentation({ apiDefinition });
        return { data: result, error: null };
      } catch (e: any) {
        return {
          data: null,
          error: e.message || 'An unexpected error occurred.',
        };
      }
    },
    { data: null, error: null }
  );

  const handleCopy = () => {
    if (state.data?.documentation) {
      navigator.clipboard.writeText(state.data.documentation);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  return (
    <Card className="mt-12">
      <CardContent className="pt-6">
        <form action={formAction} className="space-y-6">
          <div className="space-y-2">
            <Label htmlFor="apiDefinition" className="text-lg font-semibold">
              API Definition
            </Label>
            <p className="text-sm text-muted-foreground">
              Paste your OpenAPI, Swagger, or other API definition format
              below.
            </p>
            <Textarea
              id="apiDefinition"
              name="apiDefinition"
              placeholder="e.g., OpenAPI JSON or YAML..."
              rows={15}
              required
              className="font-code"
            />
          </div>
          <Button type="submit" disabled={isPending} className="w-full md:w-auto">
            {isPending ? 'Generating...' : 'Generate Documentation'}
          </Button>
        </form>

        {state.error && (
          <Alert variant="destructive" className="mt-6">
            <Terminal className="h-4 w-4" />
            <AlertTitle>Error</AlertTitle>
            <AlertDescription>{state.error}</AlertDescription>
          </Alert>
        )}

        {state.data?.documentation && (
          <div className="mt-8">
            <CardHeader className="px-0">
              <CardTitle className="flex items-center justify-between text-2xl">
                Generated Documentation
                <Button variant="ghost" size="icon" onClick={handleCopy}>
                  {copied ? (
                    <Check className="h-5 w-5 text-green-500" />
                  ) : (
                    <Copy className="h-5 w-5" />
                  )}
                  <span className="sr-only">Copy to clipboard</span>
                </Button>
              </CardTitle>
            </CardHeader>
            <div className="prose prose-sm max-w-none rounded-md border bg-secondary/50 p-4">
              <pre className="whitespace-pre-wrap bg-transparent p-0 font-code">
                <code>{state.data.documentation}</code>
              </pre>
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}
