'use client';

import { useUser } from '@/firebase';
import { useRouter } from 'next/navigation';
import { useEffect } from 'react';
import ServiceManager from '@/app/admin/service-manager';
import { Skeleton } from '@/components/ui/skeleton';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Terminal } from 'lucide-react';
import BackToPreviousButton from '@/components/back-to-previous-button';

export default function AdminPage() {
  const { user, isUserLoading } = useUser();
  const router = useRouter();

  useEffect(() => {
    // If loading is finished and there's no user, or the user is not an admin, redirect.
    if (!isUserLoading && !user?.isAdmin) {
      router.push('/');
    }
  }, [user, isUserLoading, router]);

  // Show a loading state while we verify the user's admin status
  if (isUserLoading || !user) {
    return (
      <div className="container mx-auto px-4 py-12">
        <Skeleton className="h-10 w-48 mb-4" />
        <Skeleton className="h-6 w-96 mb-12" />
        <Skeleton className="h-96 w-full" />
      </div>
    );
  }

  // If the user object is loaded but they are not an admin, show an access denied message
  // This is a fallback for the redirect, covering the brief moment before redirection occurs.
  if (!user.isAdmin) {
    return (
       <div className="flex min-h-[50vh] flex-col items-center justify-center">
        <Alert variant="destructive" className="max-w-md">
          <Terminal className="h-4 w-4" />
          <AlertTitle>Access Denied</AlertTitle>
          <AlertDescription>
            You do not have permission to view this page. Redirecting...
          </AlertDescription>
        </Alert>
      </div>
    );
  }

  // If the user is an admin, render the dashboard
  return (
    <div className="min-h-screen bg-secondary/50">
      <div className="container mx-auto px-4 py-12">
        <BackToPreviousButton />
        <header className="mb-8 mt-4">
          <h1 className="font-headline text-3xl font-bold md:text-4xl">
            Admin Dashboard
          </h1>
          <p className="mt-2 text-lg text-muted-foreground">
            Manage your ZuriPay application from one central place.
          </p>
        </header>

        <ServiceManager />
        
      </div>
    </div>
  );
}
