'use client';

import Image from 'next/image';
import Link from 'next/link';
import * as React from 'react';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';
import {
  Carousel,
  CarouselContent,
  CarouselItem,
} from '@/components/ui/carousel';
import Autoplay from 'embla-carousel-autoplay';
import BackToPreviousButton from '@/components/back-to-previous-button';
import {
  useCollection,
  useFirestore,
  useMemoFirebase,
  useUser,
} from '@/firebase';
import { collection, query, orderBy } from 'firebase/firestore';
import type { Blog } from '@/lib/data';
import { Skeleton } from '@/components/ui/skeleton';
import { Button } from '@/components/ui/button';
import { PlusCircle } from 'lucide-react';
import { fintechCarouselImages } from '@/lib/placeholder-images';

// Helper to create a clean text snippet
const createSnippet = (html: string, length = 120) => {
  const text = html.replace(/<[^>]+>/g, ''); // Strip HTML tags
  if (text.length <= length) {
    return text;
  }
  return text.substring(0, length) + '...';
};

export default function BlogPage() {
  const firestore = useFirestore();
  const { user, isUserLoading } = useUser();
  const autoplay = React.useRef(Autoplay({ delay: 5000, stopOnInteraction: false }));

  const blogsQuery = useMemoFirebase(
    () =>
      firestore
        ? query(collection(firestore, 'blogs'), orderBy('dateCreated', 'desc'))
        : null,
    [firestore]
  );

  const {
    data: blogPosts,
    isLoading,
    error,
  } = useCollection<Blog>(blogsQuery);

  return (
    <div>
      {/* Hero Section */}
      <section className="relative h-[40vh] min-h-[300px] w-full text-primary-foreground">
        <Carousel
          className="absolute h-full w-full"
          plugins={[autoplay.current]}
          opts={{
            loop: true,
          }}
        >
          <CarouselContent>
            {fintechCarouselImages.map((image) => (
              <CarouselItem key={image.id}>
                <div className="relative h-[40vh] min-h-[300px] w-full">
                  <Image
                    src={image.imageUrl}
                    alt={image.description}
                    fill
                    priority
                    className="object-cover"
                    data-ai-hint={image.imageHint}
                    sizes="100vw"
                  />
                </div>
              </CarouselItem>
            ))}
          </CarouselContent>
        </Carousel>
        <div className="absolute inset-0 bg-primary/70" />
        <div className="relative z-10 flex h-full flex-col items-center justify-center text-center">
          <h1 className="font-headline text-4xl font-extrabold tracking-tight md:text-6xl">
            ZuriPay Insights
          </h1>
          <p className="mt-4 max-w-2xl text-lg md:text-xl">
            The latest news, trends, and stories from the world of fintech.
          </p>
        </div>
      </section>

      {/* Blog Grid */}
      <section className="py-16 md:py-24">
        <div className="container mx-auto px-4">
          <div className="flex items-center justify-between">
            <BackToPreviousButton />
            {!isUserLoading && user && (
              <Button asChild>
                <Link href="/blog/new">
                  <PlusCircle className="mr-2 h-4 w-4" />
                  Create Post
                </Link>
              </Button>
            )}
          </div>
          <div className="mt-8 grid grid-cols-1 gap-8 md:grid-cols-2 lg:grid-cols-3">
            {isLoading &&
              Array.from({ length: 3 }).map((_, i) => (
                <Card key={i}>
                  <Skeleton className="h-56 w-full" />
                  <CardHeader>
                    <Skeleton className="h-6 w-3/4" />
                    <Skeleton className="mt-2 h-4 w-1/2" />
                  </CardHeader>
                  <CardContent>
                    <Skeleton className="h-4 w-full" />
                    <Skeleton className="mt-2 h-4 w-5/6" />
                  </CardContent>
                </Card>
              ))}
            {error && (
              <p className="col-span-full text-center text-destructive">
                Error loading posts. Please try again later.
              </p>
            )}
            {blogPosts && blogPosts.length === 0 && !isLoading && (
              <p className="col-span-full text-center text-muted-foreground">
                No blog posts found.
              </p>
            )}
            {blogPosts?.map((post) => (
              <Card key={post.id} className="flex flex-col overflow-hidden">
                <Link href={`/blog/${post.slug}`} className="block">
                  <div className="relative h-56 w-full">
                    <Image
                      src={post.coverImage || '/placeholder.jpg'}
                      alt={post.title}
                      fill
                      className="object-cover transition-transform duration-300 hover:scale-105"
                    />
                  </div>
                </Link>
                <CardHeader>
                  <CardTitle className="leading-tight">
                    <Link
                      href={`/blog/${post.slug}`}
                      className="hover:text-primary"
                    >
                      {post.title}
                    </Link>
                  </CardTitle>
                  <CardDescription>
                    {new Date(post.dateCreated).toLocaleDateString('en-US', {
                      year: 'numeric',
                      month: 'long',
                      day: 'numeric',
                    })}
                  </CardDescription>
                </CardHeader>
                <CardContent className="flex-1">
                  <p className="text-muted-foreground line-clamp-3">
                    {createSnippet(post.body)}
                  </p>
                </CardContent>
              </Card>
            ))}
          </div>
          {/* Future: Add pagination controls here */}
        </div>
      </section>
    </div>
  );
}
